<script setup>
import {ref,onMounted,computed} from 'vue'
const blank=()=>({name:'Homepage Test',method:'GET',path:'/',headers:'{}',body:''})
const form=ref(blank()),selected=ref(null),cases=ref([]),history=ref([]),result=ref(null),busy=ref(false),message=ref(''),error=ref(''),view=ref('workbench'),tab=ref('body')
const score=computed(()=>result.value?Math.round(result.value.score/result.value.total*100):0)
async function api(url,options={}){const res=await fetch(url,{...options,headers:{'Content-Type':'application/json',...options.headers}});const data=await res.json().catch(()=>({}));if(!res.ok)throw Error(data.detail||data.error||'Request failed');return data}
async function refresh(){try{[cases.value,history.value]=await Promise.all([api('/api/test-cases'),api('/api/history')])}catch(e){error.value=e.message}}
function choose(c){selected.value=c.id;form.value={name:c.name,method:c.method,path:c.path,headers:c.headers,body:c.body};result.value=null;view.value='workbench'}
function fresh(){selected.value=null;form.value=blank();result.value=null;view.value='workbench'}
async function save(){busy.value=true;error.value='';message.value='';try{const editing=selected.value!=null;const c=await api(editing?`/api/test-cases/${selected.value}`:'/api/test-cases',{method:editing?'PUT':'POST',body:JSON.stringify(form.value)});selected.value=c.id;await refresh();message.value=editing?'Test case updated':'Test case created'}catch(e){error.value=e.message}finally{busy.value=false}}
async function remove(){if(!selected.value||!confirm('Delete this test case?'))return;busy.value=true;error.value='';try{await api(`/api/test-cases/${selected.value}`,{method:'DELETE'});fresh();await refresh();message.value='Test case deleted'}catch(e){error.value=e.message}finally{busy.value=false}}
async function run(){busy.value=true;error.value='';message.value='';result.value=null;try{result.value=await api('/api/run',{method:'POST',body:JSON.stringify({...form.value,...(selected.value?{testCaseId:selected.value}:{})})});await refresh();message.value=`HTTP ${result.value.status} received`}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(refresh)
</script>
<template><div class="shell"><aside><div class="brand">⬡ WEBSEC <em>LAB</em></div><small>VUE · FASTAPI · SQLITE</small><h3>WORKSPACE</h3><button class="nav" @click="view='workbench'">⌘ Request builder</button><button class="nav" @click="view='library'">▤ Saved test cases ({{cases.length}})</button><button class="nav" @click="view='history'">◷ Run history</button><h3>QUICK ACCESS</h3><button class="nav" v-for="c in cases.slice(0,6)" :key="c.id" @click="choose(c)">{{c.method}} · {{c.name}}</button><div class="bottom">🔒 FIXED LOCAL TARGET<br><code>127.0.0.1:3002</code></div></aside><main><header><span>WORKSPACE / {{view.toUpperCase()}}</span><span class="pill">● LOCAL ONLY</span></header><div class="content"><h1>HTTP Security Workbench</h1><p class="muted">Build requests, save test cases, and analyze security headers.</p><div class="notice error" v-if="error">{{error}}</div><div class="notice" v-if="message">{{message}}</div><template v-if="view==='workbench'"><div class="grid"><section class="panel"><div class="panelhead"><h2>Request builder</h2><button @click="fresh">＋ New</button></div><label>Test case name<input v-model="form.name" maxlength="100"></label><div class="two"><label>Method<select v-model="form.method"><option>GET</option><option>POST</option></select></label><label>Path<input v-model="form.path"></label></div><label>Request headers (JSON)<textarea rows="4" v-model="form.headers"></textarea></label><label>Request body<textarea rows="5" v-model="form.body"></textarea></label><div class="actions"><button class="primary" :disabled="busy" @click="run">▶ Send request</button><button :disabled="busy" @click="save">▣ {{selected?'Update':'Save'}} case</button><button v-if="selected" class="danger" :disabled="busy" @click="remove">Delete</button></div></section><section class="panel"><div class="panelhead"><h2>Response viewer</h2><span class="pill" v-if="result">HTTP {{result.status}}</span></div><template v-if="result"><div class="metrics"><div><small>DURATION</small><h2>{{result.durationMs}} ms</h2></div><div><small>HEADERS</small><h2>{{result.score}}/{{result.total}}</h2></div><div><small>SCORE</small><h2>{{score}}%</h2></div></div><div class="actions"><button @click="tab='body'">Body</button><button @click="tab='headers'">Headers</button><button @click="tab='checks'">Security checks</button></div><pre v-if="tab==='body'">{{result.body}}</pre><pre v-if="tab==='headers'">{{JSON.stringify(result.headers,null,2)}}</pre><div v-if="tab==='checks'"><div class="check" v-for="c in result.checks" :key="c.header"><span>{{c.present?'✓':'✕'}} {{c.label}}</span><span>{{c.value||'Missing'}}</span></div></div></template><template v-else><p class="muted">Run a request to view status, headers, body, and security analysis.</p><div class="route" v-for="r in ['GET /','GET /secure','GET /echo','POST /echo','GET /status/404']" :key="r">{{r}}</div></template></section></div></template><section v-if="view==='library'" class="panel"><div class="panelhead"><h2>Saved test cases</h2><button @click="fresh">＋ New case</button></div><div class="tr heading"><span>Name</span><span>Method</span><span>Path</span><span>Action</span></div><div class="tr" v-for="c in cases" :key="c.id"><span>{{c.name}}</span><span>{{c.method}}</span><code>{{c.path}}</code><button @click="choose(c)">Edit</button></div><p v-if="!cases.length" class="muted">No saved test cases yet.</p></section><section v-if="view==='history'" class="panel"><div class="panelhead"><h2>Run history</h2><button @click="refresh">Refresh</button></div><div class="tr heading"><span>Method</span><span>Path</span><span>Status</span><span>Duration</span></div><div class="tr" v-for="h in history" :key="h.id"><span>{{h.method}}</span><code>{{h.path}}</code><span>{{h.status}}</span><span>{{h.duration_ms}} ms</span></div><p v-if="!history.length" class="muted">No runs yet.</p></section></div></main></div></template>